import{_ as e,o as a,c as l,a2 as o}from"./chunks/framework.CZGNF-7T.js";const h=JSON.parse('{"title":"문서함 구분 및 검색","description":"","frontmatter":{},"headers":[],"relativePath":"approval/boxes.md","filePath":"approval/boxes.md","lastUpdated":1787672404000}'),s={name:"approval/boxes.md"};function d(n,t,r,i,p,c){return a(),l("div",null,[...t[0]||(t[0]=[o(`<h1 id="문서함-구분-및-검색" tabindex="-1">문서함 구분 및 검색 <a class="header-anchor" href="#문서함-구분-및-검색" aria-label="Permalink to &quot;문서함 구분 및 검색&quot;">​</a></h1><p>전자결재 메뉴의 각 문서함의 역할과 다차원 검색/필터링 기능을 안내합니다.</p><h2 id="_1-전자결재-문서함-구성" tabindex="-1">1. 전자결재 문서함 구성 <a class="header-anchor" href="#_1-전자결재-문서함-구성" aria-label="Permalink to &quot;1. 전자결재 문서함 구성&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">문서함명</th><th style="text-align:left;">주요 대상 및 기준</th><th style="text-align:left;">권한 및 특징</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>결재 대기함</strong> (<code>/approval/pending</code>)</td><td style="text-align:left;">내가 현재 순번으로 결재해야 할 문서 (대리 결재 대상 포함)</td><td style="text-align:left;">미결재 건수가 사이드바 배지에 실시간(Red Badge)으로 카운트됨</td></tr><tr><td style="text-align:left;"><strong>기안 문서함</strong> (<code>/approval/drafted</code>)</td><td style="text-align:left;">내가 작성한 모든 기안 문서 (임시저장, 진행중, 반려, 완료)</td><td style="text-align:left;">임시저장 수정/삭제, 상신 취소(회수), 반려 건 복사 기안</td></tr><tr><td style="text-align:left;"><strong>결재 문서함</strong> (<code>/approval/approved</code>)</td><td style="text-align:left;">내가 결재선에 참여하여 최종 승인 완료된 문서</td><td style="text-align:left;">열람, 이력 확인 및 공식 PDF 다운로드/인쇄</td></tr><tr><td style="text-align:left;"><strong>전체 문서함</strong> (<code>/approval/all</code>)</td><td style="text-align:left;">내가 열람 권한(보안등급/참조자/부서공개)을 가진 회사 내 모든 결재 문서</td><td style="text-align:left;">전사/부서 공개 결재 문서 통합 검색 및 열람</td></tr></tbody></table><h2 id="_2-보안-등급별-열람-범위" tabindex="-1">2. 보안 등급별 열람 범위 <a class="header-anchor" href="#_2-보안-등급별-열람-범위" aria-label="Permalink to &quot;2. 보안 등급별 열람 범위&quot;">​</a></h2><p>전체 문서함 및 목록 조회 시 문서에 부여된 보안 등급에 따라 열람 권한이 자동 제어됩니다:</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki material-theme-palenight vp-code" tabindex="0"><code><span class="line"><span>[1등급: 비공개]  ──▶ 기안자, 결재선 참여자, 지정된 참조자만 열람 가능</span></span>
<span class="line"><span>[2등급: 부서공개] ──▶ 기안자 소속 부서원 전체 열람 가능 (기본 설정)</span></span>
<span class="line"><span>[3등급: 전사공개] ──▶ 회사 전체 임직원 열람 가능</span></span></code></pre></div><h2 id="_3-다중-조건-검색-및-필터링" tabindex="-1">3. 다중 조건 검색 및 필터링 <a class="header-anchor" href="#_3-다중-조건-검색-및-필터링" aria-label="Permalink to &quot;3. 다중 조건 검색 및 필터링&quot;">​</a></h2><p>문서함 상단의 필터 툴바를 통해 대량의 문서 중에서 필요한 건을 신속하게 조회할 수 있습니다:</p><ul><li><strong>카테고리 / 문서 유형 필터</strong>: 특정 업무(예: <code>인사/근태</code> $\\to$ <code>휴가신청서</code>)만 선택 조회</li><li><strong>진행 상태 필터</strong>: <code>진행 중</code>, <code>최종 승인</code>, <code>반려</code>, <code>임시저장</code></li><li><strong>기간 검색</strong>: 기안일자 기준 시작일 ~ 종료일 범위 지정</li><li><strong>키워드 복합 검색</strong>: 문서 번호, 기안자명, 문서 제목을 포괄하는 실시간 통합 검색</li></ul>`,10)])])}const f=e(s,[["render",d]]);export{h as __pageData,f as default};
